program.compute:
options = read('/input/options')
result = []
if exists('/output/selection'):
    existing = read('/output/selection')
    if valid(existing):
        result = existing
else:
    for k in range(goal['min_count'], goal['max_count'] + 1):
        for group in combinations(options, k):
            ids = [item['id'] for item in group]
            if valid(ids):
                result = sorted(ids, key=lambda oid: (next(item['rank'] for item in options if item['id'] == oid), oid))
                break
        if result:
            break
    if not result:
        status('report')

program.effects:
if not result:
    status('report')
else:
    if not exists('/output/selection'):
        write('/output/selection', result)
    delivery = receipt('report')
    if delivery == 'unattempted':
        send('report', 'team', result)
    elif delivery == 'unknown':
        status('report')
    if exists('/tmp/cache'):
        delete('/tmp/cache')

